bash -c python3 - << 'EOF'
import json, ast

with open("/workspace/work/dev_batch_2.json") as f:
    b2 = json.load(f)
with open("/workspace/work/gen/4.json") as f:
    g4 = json.load(f)["outputs"]

def extract_code_defs_only(text):
    # In gen/4, reply started after reply_prefix="```python\n" (check if prefix is included in text!)
    if "```python" in text:
        s = text.split("```python", 1)[1]
        if "```" in s:
            s = s.split("```", 1)[0]
    elif "```" in text:
        s = text.split("```", 1)[0]
    else:
        s = text
    try:
        tree = ast.parse(s)
        keep = [n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Import, ast.ImportFrom))]
        tree.body = keep
        return ast.unparse(tree), s
    except Exception as e:
        return None, s

passed_idx = []
for i, (t, out) in enumerate(zip(b2, g4)):
    txt = out["text"] if isinstance(out, dict) else out
    defs_code, raw_code = extract_code_defs_only(txt)
    ok = False
    err = ""
    if defs_code is None:
        err = "SYNTAX_ERR_OR_UNCLOSED"
    else:
        ns = {}
        try:
            exec(defs_code, ns)
            exec(t["test"], ns)
            ok = True
        except Exception as e:
            err = f"{type(e).__name__}: {e}"
    if ok:
        passed_idx.append(i)
    else:
        first_lines = "\n    ".join(raw_code.strip().splitlines()[:12])
        print(f"[{i:02d}] {t['id']} (entry={t['entry_point']}) -> {err} (len={len(txt)})")
        print(f"    {first_lines}\n")

print("Passing indices in gen/4 (defs_only):", passed_idx, "count:", len(passed_idx))
EOF
